from expand_a_common import *
d='p2-t1-d10'
item(d,8,'Stakeholder management bao gồm những người nào?', ['Người ảnh hưởng dự án hoặc bị ảnh hưởng bởi kết quả','Chỉ nhân viên trong nhóm viết code','Chỉ người có quyền phê duyệt ngân sách'],'a','Quan hệ và tác động hai chiều xác định phạm vi stakeholder.')
item(d,9,'Một stakeholder ảnh hưởng cao nhưng chưa quan tâm nhiều cần được ưu tiên theo hướng nào?', ['Thuyết phục bằng giá trị và giảm mối lo của họ','Chỉ thông báo định kỳ như nhóm ít liên quan','Coi là champion đã cam kết nguồn lực'],'a','Ảnh hưởng cao và quan tâm thấp có thể tạo rào cản nếu lợi ích/rủi ro chưa được giải quyết.')
item(d,10,'Vì sao sơ đồ stakeholder cần được cập nhật định kỳ?', ['Mức quan tâm và ảnh hưởng có thể đổi theo thời gian','Nhóm stakeholder được quyết định cố định bởi chức danh','Chỉ người mới gia nhập team mới làm thay đổi quan hệ'],'a','Chiến lược phải thích ứng khi người liên quan chuyển nhóm hoặc có tác nhân mới.')
item(d,14,'Trình bày “kết luận trước” nên tổ chức thông tin thế nào?', ['Đề xuất chính → lý do → số liệu/ví dụ chứng minh','Kể toàn bộ quá trình phân tích rồi mới nói đề xuất cuối','Đưa nhiều chi tiết kỹ thuật mà chưa xác định người nghe cần gì'],'a','Người nghe cần hiểu ý chính sớm rồi mới đánh giá cơ sở của đề xuất.')
item(d,15,'Stakeholder lo AI quá rủi ro. Phản hồi nào trực tiếp giải quyết mối lo?', ['Pilot nhỏ, dữ liệu thử thực và human review giảm rủi ro','Lặp lại rằng model rất tiên tiến mà không có phép thử','Đẩy ngay sang rollout rộng để chứng minh quyết tâm'],'a','Bằng chứng và cách giới hạn hậu quả phù hợp hơn lời khẳng định chung.')
item(d,16,'Trong RACI, Consulted khác Informed ở thời điểm tham gia nào?', ['Consulted góp ý trước quyết định; Informed được thông báo sau','Consulted chỉ biết sau; Informed phải duyệt trước','Cả hai là người chịu trách nhiệm cuối cùng'],'a','Phân biệt input trước và thông báo sau tránh nhầm vai trò khi phối hợp.')
item(d,17,'Một task có nhiều người Accountable dễ tạo vấn đề gì?', ['Trách nhiệm cuối bị phân tán','Tự làm rõ ai có quyền duyệt hơn một người A','Loại bỏ nhu cầu có người Responsible'],'a','Quy tắc một A cho mỗi task làm rõ đầu mối chịu trách nhiệm cuối.')
item(d,20,'Khả năng đưa AI vào hệ thống thật của khách đòi hỏi năng lực nào ngoài xây demo?', ['Làm với dữ liệu, tích hợp và quy trình thực của khách','Chỉ tối ưu prompt trên dữ liệu giả độc lập','Chỉ phát triển UI rồi để khách tự nối mọi dependency'],'a','Triển khai cần bắc cầu giữa năng lực AI và điều kiện vận hành của khách.')
item(d,21,'Những chuyên môn advisory nào có thể hỗ trợ AI team khi cần? (Chọn tất cả đáp án đúng.)',['Domain expert','Legal/compliance','AI ethics advisor','Chỉ nhóm viết inference code, không cần góc nhìn khác'],['a','b','c'],'Sản phẩm cần cả chuyên môn nghiệp vụ và kiểm soát trách nhiệm ngoài năng lực kỹ thuật.')
item(d,22,'Centralized AI team có tradeoff điển hình nào?', ['Chia sẻ kiến thức dễ nhưng có thể thành bottleneck cho nhiều đội','Luôn phản ứng nhanh nhất với mọi nhu cầu local','Không cần phối hợp vì mọi yêu cầu tự đồng nhất'],'a','Tập trung tạo chuẩn chung nhưng năng lực trung tâm có thể không theo kịp nhu cầu.')
item(d,22,'Hub-and-spoke kết hợp hai yếu tố nào?', ['Hub chuẩn hóa công cụ và engineers nhúng sát từng nhóm','Mỗi nhóm tự làm độc lập mà không có chuẩn chung','Chỉ một nhóm trung tâm nhận mọi task và không có thành viên nhúng'],'a','Mô hình hybrid tìm cân bằng tốc độ local và tính nhất quán, với yêu cầu phối hợp tốt.')
item(d,24,'Chapter và Guild khác nhau thế nào trong mô hình squad?', ['Chapter tập hợp cùng chuyên môn; Guild theo mối quan tâm tự nguyện xuyên tổ chức','Chapter là nhóm sở hữu sản phẩm; Guild là cấp phê duyệt ngân sách','Cả hai đều là squad chịu trách nhiệm một mục tiêu sản phẩm'],'a','Chapter duy trì kết nối chuyên môn, Guild kết nối chủ đề quan tâm rộng hơn.')
item(d,28,'“Trust but verify” khi dùng AI phát triển phần mềm nên phân bổ review thế nào?', ['AI hỗ trợ việc lặp lại; người tập trung bảo mật, pháp lý và trải nghiệm cần chuyên môn','Bỏ review vì agent đã tự tạo tests','Người chỉ kiểm style còn mọi quyết định rủi ro giao AI'],'a','Tự động hóa không thay trách nhiệm đánh giá những phần cần phán đoán chuyên sâu.')
item(d,29,'Một người đạt mức cao ở Technical nhưng thấp ở Governance nên được đánh giá thế nào?', ['Ghi mức từng trục độc lập và lập lộ trình bổ sung','Gán mức cao nhất cho mọi trục vì đã giỏi kỹ thuật','Hạ toàn bộ năng lực về mức thấp nhất mà không chỉ rõ khoảng trống'],'a','Technical, Business và Governance mô tả những năng lực khác nhau.')
item(d,30,'Competency framework nên được nối với quyết định thực nào?', ['Lộ trình học, vai trò và phạm vi trách nhiệm','Chỉ tạo bảng xếp hạng không dùng cho phát triển','Chỉ ghi số năm làm việc thay cho năng lực thể hiện'],'a','Framework có ích khi làm rõ khoảng trống và bước phát triển/career tiếp theo.')
item(d,31,'Quyết định hire, outsource hay partner nên dựa trước hết vào đâu?', ['Năng lực hiện có và khoảng trống cần lấp','Chỉ xu hướng chức danh đang phổ biến','Luôn tuyển mọi chuyên môn full-time dù chưa cần'],'a','Biết gap giúp chọn cách bổ sung nguồn lực phù hợp thay vì xây đội theo danh sách chức danh.')
item(d,32,'Agentic SDLC cần governance rõ nhất ở điểm nào?', ['Agent được tự quyết ở đâu và phải dừng hỏi người ở đâu','Chỉ agent viết code nhanh đến đâu','Chỉ số tests tự sinh mà không xét quyền triển khai'],'a','Tự chủ xuyên lifecycle cần giới hạn cho dữ liệu khách, bảo mật và tiền bạc.')
d='p2-t1-d11'
item(d,6,'Đã cấp công cụ AI và được IT cho phép nhưng workflow chưa đổi phản ánh mốc nào?', ['Deployment, chưa đủ bằng chứng adoption','Normalization vì mọi người có quyền truy cập','Adoption chỉ vì đã mua license'],'a','Adoption cần thay đổi công việc, owner và handoff, vượt sự sẵn có của công cụ.')
item(d,7,'Những dấu hiệu nào cho thấy AI đã được thiết kế vào công việc? (Chọn tất cả đáp án đúng.)',['Có bước công việc cụ thể dùng AI','Có owner kết quả cuối và cách kiểm tra khi AI sai','Người dùng biết khi nào nên và không nên dùng','Chỉ có số license tăng mà trách nhiệm không đổi'],['a','b','c'],'Thiết kế workflow cần hành động, trách nhiệm và kiểm soát có thể quan sát.')
item(d,9,'Để phân biệt thiếu kỹ năng với thiếu trust khi adoption thấp, nên chẩn đoán thế nào?', ['Hỏi người dùng kẹt ở động lực/khả năng và cách kiểm chứng, xử lý lỗi hiện có','Mặc định mọi ít dùng là chống đối thay đổi','Chỉ đo thêm số lần đăng nhập để suy ra nguyên nhân'],'a','Triệu chứng usage cần được giải thích bằng các điểm nghẽn cụ thể trong con người và quy trình.')
item(d,10,'Trợ lý nội bộ ít được dùng vì không có nguồn và owner cập nhật tài liệu. Nên ưu tiên gì?', ['Sửa trust và quy trình dữ liệu trước khi thúc ép tăng usage','Chỉ tổ chức cuộc thi số prompt để tăng lượt dùng','Mở rollout rộng vì nhiều người sẽ tự sửa câu trả lời'],'a','Nguồn không được quản lý và khó kiểm chứng làm hành vi ít dùng có cơ sở thực tế.')
item(d,11,'Workflow tra cứu bằng AI cần bổ sung gì để câu trả lời được sử dụng có trách nhiệm?', ['Nguồn/ngày, người kiểm chứng và cách dừng/báo lỗi','Chỉ thay ô tìm file bằng ô chat','Tự coi mọi response là bản tài liệu chính thức'],'a','AI tăng tốc tìm/tóm tắt nhưng phải có bước kiểm tra và xử lý bất định.')
item(d,12,'Nhân viên biết cách dùng AI nhưng chưa làm được trong task thật đang cần hỗ trợ ở yếu tố ADKAR nào?', ['Ability: thực hành và hỗ trợ tại công việc','Awareness: chỉ giải thích lý do thay đổi','Reinforcement: chỉ thưởng sau khi hành vi đã ổn định'],'a','Biết cách làm là Knowledge; thực hiện được trong thực tế là Ability.')
item(d,12,'ADKAR dùng Reinforcement để giải quyết nhu cầu nào?', ['Duy trì hành vi mới bằng phản hồi và theo sát','Chỉ giới thiệu công cụ lần đầu','Chỉ làm rõ vì sao thay đổi là cần thiết'],'a','Hành vi mới cần được củng cố sau giai đoạn hiểu, muốn và có khả năng thực hiện.')
item(d,13,'Đào tạo cách hỏi chưa đủ khi nhân viên không thấy nguồn để tin câu trả lời. Cần bổ sung gì?', ['Nguồn kiểm chứng và hỗ trợ ngay trong workflow','Chỉ lặp lại cùng buổi training nhiều lần','Chỉ đặt target số câu hỏi cao hơn'],'a','Can thiệp cần khớp điểm nghẽn trust thay vì coi mọi vấn đề là thiếu knowledge.')
item(d,14,'Những điều kiện readiness nào cần kiểm trước mở rộng? (Chọn tất cả đáp án đúng.)',['Data owner và lịch cập nhật','Quyền truy cập đúng mục đích','Phạm vi, chi phí và năng lực vận hành rõ','Chỉ có model hoạt động trong demo'],['a','b','c'],'Readiness gồm nguồn lực và kiểm soát của tổ chức, không chỉ model chạy được.')
item(d,15,'Mức sử dụng tăng nhưng effort và kết quả nghiệp vụ không tốt hơn cho thấy điều gì?', ['Activity chưa đủ chứng minh giá trị adoption','Số lần dùng tự bảo đảm productivity tăng','Chỉ cần đổi target để ghi nhận thành công'],'a','Cần đi từ usage/hành vi đến năng suất, chất lượng và kết quả thật.')
item(d,16,'Chỉ số nào có bằng chứng trực tiếp hơn tự khai thời gian tiết kiệm?', ['Thời gian xử lý từ log task và tỷ lệ hoàn thành không cần QA làm lại','Số người nói họ thích có AI','Tỷ lệ nội dung có nhãn “dùng AI” bất kể chất lượng'],'a','Task logs và rework gắn với công việc thực, giúp ra quyết định dựa dữ liệu kiểm được.')
item(d,18,'Muốn làm rõ ai giữ quyết định và ai kiểm output trong workflow, framework nào phù hợp nhất?', ['Mollick để chia phần việc người–AI','ADKAR chỉ để phân chia quyền phê duyệt task','Gartner-Lite chỉ để xác định format output của model'],'a','Các framework giải quyết câu hỏi khác nhau; phân công người–AI cần ranh giới công việc và handoff.')
item(d,19,'Gartner-Lite tách Direction, Readiness và Absorption để kiểm điều gì?', ['Hướng giá trị rõ, điều kiện đủ và khả năng duy trì cách làm mới','Chỉ model được chọn có benchmark cao nhất không','Chỉ số người đã tham gia buổi giới thiệu công cụ'],'a','Khả năng hấp thụ cần owner, hỗ trợ và học từ lỗi để vận hành bền.')
item(d,20,'Mục tiêu tra cứu rõ nhưng dữ liệu, quyền và quality owner chưa sẵn sàng. Quyết định phù hợp là gì?', ['Pilot nhỏ để sửa readiness trước rollout rộng','Mở rộng ngay vì Direction đã rõ','Mua thêm license để tự giải quyết governance'],'a','Một hướng đúng chưa đủ điều kiện mở rộng khi hệ thống chưa có nguồn và trách nhiệm vận hành.')
item(d,21,'Task nào phù hợp tự động hóa hơn trong phân chia người–AI?', ['Task lặp lại, rủi ro thấp và có tiêu chí kiểm tra','Phê duyệt cuối các ngoại lệ rủi ro cao chưa có rule','Chịu trách nhiệm thay con người cho mọi hậu quả nghiệp vụ'],'a','Tự động hóa cần điều kiện rõ; quyết định cuối và xử lý ngoại lệ vẫn cần người có trách nhiệm.')
item(d,23,'Roadmap 30–60–90 nên được dùng như thế nào?', ['Ba cổng evidence để chứng minh vấn đề, chất lượng rồi quyết định mở rộng','Lịch cứng buộc rollout ngày 90 bất kể kết quả','Danh sách tasks không cần owner hay tiêu chí hoàn tất'],'a','Qua giai đoạn dựa trên evidence, không chỉ thời gian đã trôi.')
item(d,30,'Một dashboard hành động cần nối metric với những thông tin nào? (Chọn tất cả đáp án đúng.)',['Baseline và target','Nguồn dữ liệu và owner','Hành động nếu metric xấu','Chỉ giá trị hiện tại để người xem tự suy mọi quyết định'],['a','b','c'],'Metric hữu ích phải dẫn đến tiếp tục, sửa hoặc dừng với trách nhiệm rõ.')
